input.command:
cd /tmp/i02 && rm -rf p1 p2 p3 && mkdir -p p1/.zk p2/.zk p3
# p1: .zk empty dir
python3 /tmp/zkh/mknb.py /tmp/i02/p2 >/dev/null 2>&1; rm -f /tmp/i02/p2/.zk/config.toml
echo "=== p1: empty .zk dir exists"; (cd /tmp/i02/p1 && /workspace/executable init --no-input; echo "EXIT=$?")
echo "=== p2: .zk with migrated db + templates, no config.toml"; (cd /tmp/i02/p2 && /workspace/executable init --no-input; echo "EXIT=$?"); ls -la /tmp/i02/p2/.zk
echo "=== p3: full notebook exists"; python3 /tmp/zkh/mknb.py /tmp/i02/p3 >/dev/null 2>&1; (cd /tmp/i02/p3 && /workspace/executable init --no-input; echo "EXIT=$?")

cd /tmp/i02 && for case in cfgonly tplonly dbempty dbfile zkfile; do
 d=/tmp/i02/e_$case; rm -rf $d; mkdir -p $d
 case $case in
  cfgonly) mkdir $d/.zk; echo -n '' > $d/.zk/config.toml;;
  tplonly) mkdir -p $d/.zk/templates;;
  dbempty) mkdir $d/.zk; : > $d/.zk/notebook.db;;
  dbfile) mkdir $d/.zk; echo garbage > $d/.zk/notebook.db;;
  zkfile) echo hi > $d/.zk;;
 esac
 echo "=== $case"; (cd $d && /workspace/executable init --no-input 2>&1 | cat -A; echo "EXIT=${PIPESTATUS[0]}")
 echo "  files: $(cd $d && find . | sort | tr '\n' ' ')"
done
